SELECT u.*, d.dept_name AS dept_name, p.post_name AS post_name
FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id
LEFT JOIN sys_post p ON u.post_id = p.id WHERE u.username = #{username}

SELECT u.*, d.dept_name AS dept_name, p.post_name AS post_name
FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id
LEFT JOIN sys_post p ON u.post_id = p.id WHERE u.id = #{id}
